-- The SusanooExecutable module is an executable generated by the CutsceneManager plugin.
-- This is a client-side executable, so it should be required through a locally handled system or Controller.
--
-- 2026-11-09: the new 5-waypoint path (5.75 s: 0 + 1.75 + 0 + 3 + 1, then
-- the last shot held HOLD_LAST_SECONDS: 5.9 s; waypoint 2 was 3 s until
-- 2026-11-10) and its sound cues (SOUND_CUES). The camera follows the parts of
-- GameAssets.CutsceneWaypoints.SusanooWaypoints ("1".."5", pivoted on its
-- HumanoidRootPart), placed on the caster's root; the hashmap's `instance`
-- strings are the plugin's record of where they were authored and are not
-- read. The previous 2-waypoint version is in git history.

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local TweenService = game:GetService("TweenService")
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local ContentProvider = game:GetService("ContentProvider")
local GameClock = require(ReplicatedStorage.Submodules.Core.Shared.GameClock)
local Attributes = require(ReplicatedStorage.Submodules.Core.Shared.Enums.Attributes)
local ScreenVfx = require(script.Parent.Parent.ScreenVfx)

-- The last waypoint's shot is held this long before the camera (and the
-- caster's movement) is handed back. ArcaneData's cutscene.duration
-- counts it.
-- 0.15 s since 2026-11-10 (1 s, then 0.4 s: it lingered after the
-- Sharingan).
local HOLD_LAST_SECONDS = 0.15

-- World-space nudges on top of a waypoint part's CFrame, by waypoint
-- number (2026-11-09: 4 and 5 sit half a stud lower).
local WAYPOINT_OFFSETS: { [number]: Vector3 } = {
	[4] = Vector3.new(0, -0.5, 0),
	[5] = Vector3.new(0, -0.5, 0),
}

-- The cutscene's sounds, `at` seconds after it starts. Edit freely: the
-- times are independent of each other. (Cue 2, 74480184405444 at 1.25,
-- cut 2026-11-10.) Cue 1 comes with ArcaneData's first dialogue line, and
-- cue 3 leads the second by 0.5 s: move them together.
-- endVolume: the volume eases from `volume` to this from fadeAfter seconds
-- into the sound (0 when unset), over fadeSeconds (to its end when unset).
local SOUND_CUES: { { name: string, id: number, at: number, volume: number, endVolume: number?, fadeAfter: number?, fadeSeconds: number? } } =
	{
		{ name = "Cue 1", id = 74475345511331, at = 0.15, volume = 0.6 },
		-- The "cut you down" line: 0.45, down to 0.3 from 2.75 s into it over
		-- 1.2 s (2026-11-11; a flat 0.6, then 0.35). Its voice runs ~1-5 s of
		-- the 6 s clip, loudest 3.6-4.7 s (measured): a fade to the clip's end
		-- landed in the quiet tail and was barely heard.
		{
			name = "Cue 3",
			id = 130723176825812,
			at = 1,
			volume = 0.45,
			endVolume = 0.3,
			fadeAfter = 2.75,
			fadeSeconds = 1.2,
		},
		{ name = "Cue 4 (eye, 0.05 s before waypoint 5 starts)", id = 88674994331303, at = 4.7, volume = 3 },
		{ name = "Cue 5 (Susanoo)", id = 106566975780710, at = 4.75, volume = 0.6 },
	}

-- Screen effects (2026-11-10): parts of GameAssets.VFX["Susanoo
-- Cutscene"], held `distance` studs in front of the camera with
-- their front face toward it, every frame right after the camera moves
-- (so they stay put through the waypoint moves and the hand-back), and
-- emitted `at` seconds in (their emitters' EmitCount / EmitDelay
-- attributes, emitAttributeVFX). Each is removed once its particles are
-- done. The Sharingan bursts 0.05 s after cue 4, the flames with it (seen 0.45 s on: their EmitDelay)
-- (2026-11-10; at the hand-back before). Nearer the camera = bigger on
-- screen. `emitScale` multiplies every emitter's EmitCount.
-- An emitter directly on the part spawns anywhere in its box: the copy is
-- flattened (ScreenVfx DEPTH) and trimmed to the screen's size at its
-- distance (2026-11-10: SusanooFlames is 2 studs deep and 4 wide, so at
-- 0.9 studs half its flames spawned behind the camera or off screen).
-- `sustain`: after its burst it keeps streaming (each emitter's own Rate x
-- streamScale, from its EmitDelay) until the camera is handed back, then
-- tapers to nothing over ScreenVfx's SUSTAIN_TAIL_SECONDS (2026-11-10: it cut off at
-- full strength, and the pile-up at the hand-back was too much) (2026-11-10: the flames' burst alone was over
-- before the hand-back).
-- 2026-11-10: the flames' x3 burst and stream were far too strong; now
-- the burst as authored and the stream at 25% (40% until it was still a
-- bit much at the hand-back).
-- `delayShift` is added to every emitter's EmitDelay (clamped at 0): the
-- flames' authored 0.45 s, 0.1 s shorter: they show at 5.1 s (2026-11-10).
-- `layer` is added to every emitter's ZOffset (studs toward the camera):
-- the Sharingan always draws over the flames (2026-11-10). Kept small, as
-- at 0.9 studs it also nudges the size a few percent.
local SCREEN_VFX_CUES: { ScreenVfx.Cue } = {
	{
		name = "SharinganActivation",
		at = 4.75,
		distance = 0.9,
		emitScale = 1,
		sustain = false,
		streamScale = 1,
		delayShift = 0,
		layer = 0.05,
		-- Its faint warm-up copy showed (2026-11-10).
		warm = false,
	},
	{
		name = "SusanooFlames",
		at = 4.75,
		-- 2 studs through the cutscene, easing back to 8 after it, and a bit
		-- more of them (burst x1.5, stream 0.35; 2026-11-11).
		distance = 2,
		endDistance = 8,
		endDistanceSeconds = 0.6,
		emitScale = 1.5,
		sustain = true,
		streamScale = 0.35,
		delayShift = -0.1,
		layer = -0.05,
		-- Its faint warm-up copy showed too (2026-11-10).
		warm = false,
	},
}

-- Where a standing character's root would be over the floor under `root`
-- (2026-11-10): the path is placed from this, not the root's height at the
-- cast, which a roll or a hop leaves lower or higher -- the whole shot came
-- out from a lower angle after a roll.
local function standingRootPosition(character: Model, root: BasePart): Vector3
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	local ignore: { Instance } = { character }
	local ignoreFolder = workspace:FindFirstChild("IgnoreInstances")
	if ignoreFolder then
		for _, child in ignoreFolder:GetChildren() do
			if child.Name ~= "Map" then
				table.insert(ignore, child)
			end
		end
	end
	-- Nor the players' waiting platforms (no collision, but they stop a
	-- ray: the path came out 1.5 studs high on one, 2026-11-11), and only
	-- floors that can be stood on.
	local baseplates = workspace:FindFirstChild("PlayerBaseplates")
	if baseplates then
		table.insert(ignore, baseplates)
	end
	params.FilterDescendantsInstances = ignore
	params.RespectCanCollide = true
	local hit = workspace:Raycast(root.Position + Vector3.new(0, 2, 0), Vector3.new(0, -20, 0), params)
	if not hit or not humanoid then
		return root.Position
	end
	-- R6 stands on its legs (HipHeight 0); R15 on HipHeight (2026-11-10:
	-- HipHeight alone put an R6 path two studs low).
	local leg = character:FindFirstChild("Left Leg")
	local legHeight = if humanoid.RigType == Enum.HumanoidRigType.R6
			and leg
			and leg:IsA("BasePart")
		then leg.Size.Y
		else humanoid.HipHeight
	local standHeight = legHeight + root.Size.Y / 2
	return Vector3.new(root.Position.X, hit.Position.Y + standHeight, root.Position.Z)
end

local SusanooExecutable = {}

SusanooExecutable.Enabled = true :: boolean
SusanooExecutable.CutsceneConnection = nil :: Tween?
SusanooExecutable.CutsceneHashmap = {
