} :: CutsceneIndex

-- The sounds this play started (stopped early by Stop).
local playingSounds: { Sound } = {}

local function startSoundCues(isCurrent: () -> boolean)
	for _, cue in SOUND_CUES do
		GameClock.Delay(cue.at, function()
			if not isCurrent() then
				return
			end
			local sound = Instance.new("Sound")
			sound.Name = "SusanooCutscene_" .. cue.name
			sound.SoundId = "rbxassetid://" .. tostring(cue.id)
			sound.Volume = cue.volume
			-- Not muted by the cutscene's own isolation.
			sound:SetAttribute(Attributes.CutsceneAudio, true)
			sound.Parent = workspace.CurrentCamera
			sound:Play()
			local endVolume = cue.endVolume
			if endVolume then
				local fadeAfter = cue.fadeAfter or 0
				local function fade()
					if not sound.Parent or sound.TimeLength <= 0 then
						return
					end
					local seconds = cue.fadeSeconds or math.max(sound.TimeLength - fadeAfter, 0.1)
					GameClock.Delay(math.max(fadeAfter - sound.TimePosition, 0), function()
						if sound.Parent then
							TweenService:Create(
								sound,
								TweenInfo.new(seconds, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
								{ Volume = endVolume }
							):Play()
						end
					end)
				end
				if sound.IsLoaded then
					fade()
				else
					sound.Loaded:Once(fade)
				end
			end
			table.insert(playingSounds, sound)
			sound.Ended:Once(function()
				local index = table.find(playingSounds, sound)
				if index then
					table.remove(playingSounds, index)
				end
				sound:Destroy()
			end)
			-- A sound that never loads must not linger.
			GameClock.Debris(sound, 30)
		end)
	end
end

-- The screen effects (ScreenVfx, shared with Domain Expansion).
local screenVfx = ScreenVfx.new("Susanoo")
local warmSerial = 0

-- The Susanoo's OWN particles (the rig's, its cast and spawn bursts,
-- GameAssets.VFX["Susanoo Armor"]) kept warm the same way, from the
-- cutscene's start until ARMOR_WARM_SECONDS (2026-11-10: they sometimes
-- came in unloaded as the rig rose, at 5 s). Every emitter's clone rides
-- one holder part in front of the camera, at its own authored size.
local ARMOR_WARM_SECONDS = 6.5
-- Dozens of emitters overlap here, so each draws only a blink a second,
-- fainter still: stacked, they must never add up to a visible haze.
local ARMOR_WARM_TRANSPARENCY = 0.995
local ARMOR_WARM_RATE = 1
local ARMOR_WARM_LIFETIME = 0.1

local function warmArmorVfx(armorFolder: Instance)
	local holder = Instance.new("Part")
	holder.Name = "SusanooArmorWarm"
	holder.Anchored = true
	holder.CanCollide = false
	holder.CanQuery = false
	holder.CanTouch = false
	holder.CastShadow = false
	holder.Transparency = 1
	holder.Size = Vector3.new(4, 4, 0.05)
	for _, emitter in armorFolder:GetDescendants() do
		if emitter:IsA("ParticleEmitter") then
			local copy = emitter:Clone()
			for _, child in copy:GetChildren() do
				child:Destroy()
			end
			copy.Transparency = NumberSequence.new(ARMOR_WARM_TRANSPARENCY)
			copy.Rate = ARMOR_WARM_RATE
			copy.Lifetime = NumberRange.new(ARMOR_WARM_LIFETIME)
			copy.Speed = NumberRange.new(0)
			copy.TimeScale = 1
			copy.Enabled = true
			copy.Parent = holder
		end
	end
	warmSerial += 1
	local bind = "SusanooArmorWarm" .. warmSerial
	local function place()
		local camera = workspace.CurrentCamera
		if camera then
			holder.CFrame = camera.CFrame * CFrame.new(0, 0, -6) * CFrame.Angles(0, math.pi, 0)
		end
	end
	place()
	holder.Parent = workspace.CurrentCamera
	RunService:BindToRenderStep(bind, Enum.RenderPriority.Camera.Value + 1, place)
	GameClock.Delay(ARMOR_WARM_SECONDS, function()
		RunService:UnbindFromRenderStep(bind)
		holder:Destroy()
	end)
end

local function startScreenVfx(isCurrent: () -> boolean)
	local vfxFolder = ReplicatedStorage.GameAssets:FindFirstChild("VFX")
	local folder = vfxFolder and vfxFolder:FindFirstChild("Susanoo Cutscene")
	local armorFolder = vfxFolder and vfxFolder:FindFirstChild("Susanoo Armor")
	if armorFolder then
		warmArmorVfx(armorFolder)
		task.spawn(function()
			ContentProvider:PreloadAsync({ armorFolder })
		end)
	end
	if folder then
		screenVfx:Start(folder, SCREEN_VFX_CUES, isCurrent)
	end
end

-- Bumped per play, so a stopped play's pending cues stay silent.
local playToken = 0

--- Iterates through hashmap and plays the cutscene.
function SusanooExecutable:Play()
	local waypointModel = ReplicatedStorage.GameAssets.CutsceneWaypoints.SusanooWaypoints:Clone()
	local character = Players.LocalPlayer.Character
	local root = character.HumanoidRootPart :: BasePart
	-- Placed on the root's position and its FLAT facing (yaw only): a roll
	-- or lunge in flight can pitch the root, and the path tilted with it.
	local look = root.CFrame.LookVector
	local flatLook = Vector3.new(look.X, 0, look.Z)
	if flatLook.Magnitude < 1e-3 then
		flatLook = Vector3.new(0, 0, -1)
	end
	local startPosition = standingRootPosition(character, root)
	local placement = CFrame.lookAt(startPosition, startPosition + flatLook.Unit)
	waypointModel:PivotTo(placement)

	-- The caster stays where the path was placed, facing as it was placed
	-- (2026-11-09): a swing's or spell's turn still in flight rotated the
	-- body away from the camera, and a roll's momentum carried it on
	-- toward the fixed waypoints, so the close shots ended up in its face.
	-- Every frame the root goes back to the start's ground position (its
	-- height left free) and facing, with its sideways momentum dropped;
	-- AutoRotate off for the length, restored after.
	local facing = placement.Rotation
	local function pinRoot()
		root.CFrame = CFrame.new(startPosition.X, root.Position.Y, startPosition.Z) * facing
		local velocity = root.AssemblyLinearVelocity
		root.AssemblyLinearVelocity = Vector3.new(0, velocity.Y, 0)
	end
	pinRoot()
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	local autoRotateBefore = humanoid and humanoid.AutoRotate
	if humanoid then
		humanoid.AutoRotate = false
	end
	local holdFacing = RunService.PreRender:Connect(function()
		if root.Parent then
			pinRoot()
		end
	end)
	waypointModel.Parent = workspace.IgnoreInstances.ArcaneSpells

	SusanooExecutable.Enabled = true
	playToken += 1
	local token = playToken
	local function isCurrent(): boolean
		return playToken == token and SusanooExecutable.Enabled
	end
	startSoundCues(isCurrent)
	startScreenVfx(isCurrent)

	local waypointTotal = 0

	local hashmap = self.CutsceneHashmap

	for _, _ in hashmap do
		waypointTotal += 1
	end

	local previousCameraType = workspace.CurrentCamera.CameraType
	local previousCameraFieldOfView = workspace.CurrentCamera.FieldOfView
	-- The last waypoint's shot, re-pinned through the hold.
	local lastCFrame: CFrame? = nil
	local lastFieldOfView: number? = nil

	for i = 1, waypointTotal do
		local waypointData = hashmap["Waypoint" .. i]
		local tweenInfo = TweenInfo.new(
			tonumber(waypointData.duration),
			(Enum.EasingStyle :: any)[waypointData.easingStyle],
			(Enum.EasingDirection :: any)[waypointData.easingDirection],
			0,
			false,
			tonumber(waypointData.delay)
		)

		local finalCameraTilt = if waypointData.tilt == 0
			then 0
			else math.rad(waypointData.tilt) - workspace.CurrentCamera.CFrame:ToOrientation()
		local finalCameraCFrame = (waypointModel[tostring(i)].CFrame + (WAYPOINT_OFFSETS[i] or Vector3.zero))
			* CFrame.Angles(0, 0, finalCameraTilt)
		lastCFrame = finalCameraCFrame
		lastFieldOfView = tonumber(waypointData.fov)

		SusanooExecutable.CutsceneConnection = GameClock.Tween(workspace.CurrentCamera, tweenInfo, {
			CFrame = finalCameraCFrame,
			FieldOfView = tonumber(waypointData.fov),
		})

		workspace.CurrentCamera.CameraType = Enum.CameraType.Scriptable

		SusanooExecutable.CutsceneConnection:Play()
		SusanooExecutable.CutsceneConnection.Completed:Wait()

		if not SusanooExecutable.Enabled then
			break
		end
	end

	-- The hold: a tween onto the last shot, so Stop's Cancel ends it like
	-- any waypoint. It must write the CFrame every frame: CutsceneController's
	-- cinematic bob offsets the camera's CURRENT CFrame each frame, and with
	-- nothing rewriting it those offsets pile up and the shot drifts.
	if SusanooExecutable.Enabled and HOLD_LAST_SECONDS > 0 and lastCFrame then
		SusanooExecutable.CutsceneConnection = GameClock.Tween(
			workspace.CurrentCamera,
			TweenInfo.new(HOLD_LAST_SECONDS, Enum.EasingStyle.Linear),
			{ CFrame = lastCFrame, FieldOfView = lastFieldOfView or workspace.CurrentCamera.FieldOfView }
		)
		SusanooExecutable.CutsceneConnection:Play()
		SusanooExecutable.CutsceneConnection.Completed:Wait()
	end

	workspace.CurrentCamera.CameraType = previousCameraType
	workspace.CurrentCamera.FieldOfView = previousCameraFieldOfView
	screenVfx:EndSustained()

	-- The waypoint rig is only needed while the tweens read it; without this
	-- every play left one more clone in ArcaneSpells.
	waypointModel:Destroy()

	holdFacing:Disconnect()
	if humanoid and autoRotateBefore ~= nil then
		humanoid.AutoRotate = autoRotateBefore
	end
end

--- Stops any existing cutscenes that resembles the passed hashmap.
function SusanooExecutable:Stop(hashmap: CutsceneIndex)
	if hashmap ~= SusanooExecutable.CutsceneHashmap then
		return
	end

	SusanooExecutable.Enabled = false
	if SusanooExecutable.CutsceneConnection then
		SusanooExecutable.CutsceneConnection:Cancel()
	end
	for _, sound in playingSounds do
		sound:Destroy()
	end
	table.clear(playingSounds)
	screenVfx:StopAll()
end

export type SusanooExecutable = typeof(SusanooExecutable)

export type CutsceneIndex = {
	[string]: {
		iteration: number,
		instance: BasePart,
		fov: number,
		tilt: number,
		delay: number,
		duration: number,
		easingStyle: string,
		easingDirection: string,
	},
}

return SusanooExecutable :: SusanooExecutable
